#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define OUTBUF_SIZE 1024
static char main_out[OUTBUF_SIZE];

static size_t to_camel(const char *src) {
    size_t out = 0;
    int up_next = 0;
    while (*src && out + 1 < OUTBUF_SIZE) {
        if (*src == '_') {
            up_next = 1;
        } else {
            char ch = *src;
            if (up_next) {
                ch = (char)toupper((unsigned char)ch);
                up_next = 0;
            }
            main_out[out++] = ch;
        }
        ++src;
    }
    main_out[out] = '\0';
    return out;
}

static size_t to_snake(const char *src) {
    size_t out = 0;
    while (*src && out + 2 < OUTBUF_SIZE) {
        char ch = *src;
        if (isupper((unsigned char)ch)) {
            main_out[out++] = '_';
            ch = (char)tolower((unsigned char)ch);
        }
        main_out[out++] = ch;
        ++src;
    }
    main_out[out] = '\0';
    return out;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *mode = argv[1];
    const char *input = argv[2];
    if (strcmp(mode, "to_camel") == 0) {
        to_camel(input);
        puts(main_out);
    } else if (strcmp(mode, "to_snake") == 0) {
        to_snake(input);
        puts(main_out);
    } else {
        puts("INVALID_MODE");
    }
    return 0;
}
